old_actor_block = '''    private void updateActors(String cast) {\n        actorsStrip.removeAllViews();\n        ArrayList<String> names = parseCast(cast);\n        if (names.isEmpty()) {\n            for (int i = 0; i < 6; i++) addActorCard("—");\n            return;\n        }\n        int count = Math.min(6, names.size());\n        for (int i = 0; i < count; i++) addActorCard(names.get(i));\n    }\n\n    private void showActorPlaceholders() {\n        actorsStrip.removeAllViews();\n        for (int i = 0; i < 6; i++) addActorCard("—");\n    }\n\n    private void addActorCard(String name) {\n        LinearLayout card = new LinearLayout(this);\n        card.setOrientation(LinearLayout.VERTICAL);\n        card.setGravity(Gravity.CENTER_HORIZONTAL);\n        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(pW(0.079f), ViewGroup.LayoutParams.MATCH_PARENT);\n        cardLp.rightMargin = pW(0.008f);\n\n        TextView photo = label("", 0.018f, GOLD_BRIGHT, Gravity.CENTER, false);\n        photo.setBackground(round(Color.rgb(8, 8, 8), GOLD, dp(8), Math.max(1, dp(1))));\n        card.addView(photo, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, pH(0.145f)));\n\n        TextView actorName = label(name, 0.014f, Color.WHITE, Gravity.CENTER, false);\n        actorName.setSingleLine(false);\n        actorName.setMaxLines(2);\n        actorName.setEllipsize(TextUtils.TruncateAt.END);\n        card.addView(actorName, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, pH(0.046f)));\n\n        actorsStrip.addView(card, cardLp);\n    }'''

new_actor_block = '''    private void updateActors(ArrayList<ActorEntry> actors) {\n        actorsStrip.removeAllViews();\n        if (actors == null || actors.isEmpty()) {\n            for (int i = 0; i < 6; i++) addActorCard(new ActorEntry("—", ""));\n            return;\n        }\n        int count = Math.min(6, actors.size());\n        for (int i = 0; i < count; i++) addActorCard(actors.get(i));\n    }\n\n    private void showActorPlaceholders() {\n        actorsStrip.removeAllViews();\n        for (int i = 0; i < 6; i++) addActorCard(new ActorEntry("—", ""));\n    }\n\n    private void addActorCard(final ActorEntry actor) {\n        LinearLayout card = new LinearLayout(this);\n        card.setOrientation(LinearLayout.VERTICAL);\n        card.setGravity(Gravity.CENTER_HORIZONTAL);\n        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(pW(0.079f), ViewGroup.LayoutParams.MATCH_PARENT);\n        cardLp.rightMargin = pW(0.008f);\n\n        FrameLayout photoFrame = new FrameLayout(this);\n        photoFrame.setBackground(round(Color.rgb(8, 8, 8), GOLD, dp(8), Math.max(1, dp(1))));\n        ImageView photo = new ImageView(this);\n        photo.setScaleType(ImageView.ScaleType.CENTER_CROP);\n        photo.setBackground(round(Color.rgb(8, 8, 8), Color.TRANSPARENT, dp(7), 0));\n        photo.setClipToOutline(true);\n        FrameLayout.LayoutParams photoLp = new FrameLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);\n        int inset = dp(2);\n        photoLp.setMargins(inset, inset, inset, inset);\n        photoFrame.addView(photo, photoLp);\n        card.addView(photoFrame, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, pH(0.145f)));\n\n        if (!TextUtils.isEmpty(actor.image)) {\n            loadImage(actor.image, photo);\n        } else if (!TextUtils.isEmpty(actor.name) && !"—".equals(actor.name)) {\n            loadActorImageFallback(actor.name, photo);\n        }\n\n        TextView actorName = label(actor.name, 0.014f, Color.WHITE, Gravity.CENTER, false);\n        actorName.setSingleLine(false);\n        actorName.setMaxLines(2);\n        actorName.setEllipsize(TextUtils.TruncateAt.END);\n        card.addView(actorName, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, pH(0.046f)));\n\n        actorsStrip.addView(card, cardLp);\n    }'''
rep(old_actor_block, new_actor_block, 'actor card block')

old_similar_load = '''    private void loadSimilarMovies(final String category) {\n        if (TextUtils.isEmpty(category) || host.length() == 0) return;\n        io.execute(new Runnable() {\n            @Override public void run() {\n                try {\n                    JSONArray arr = new JSONArray(httpGet(apiUrl("get_vod_streams", "&category_id=" + enc(category))));\n                    final ArrayList<SimilarMovie> items = new ArrayList<SimilarMovie>();\n                    for (int i = 0; i < arr.length(); i++) {\n                        JSONObject o = arr.optJSONObject(i);\n                        if (o == null) continue;\n                        String id = o.optString("stream_id", "");\n                        if (id.length() == 0 || id.equals(vodId)) continue;\n                        items.add(new SimilarMovie(\n                                id,\n                                o.optString("name", "Film"),\n                                o.optString("stream_icon", ""),\n                                firstNonEmpty(o.optString("container_extension", ""), "mp4"),\n                                o.optLong("added", 0L)));\n                    }\n                    Collections.sort(items, new Comparator<SimilarMovie>() {\n                        @Override public int compare(SimilarMovie a, SimilarMovie b) {\n                            if (a.added < b.added) return 1;\n                            if (a.added > b.added) return -1;\n                            return b.id.compareTo(a.id);\n                        }\n                    });\n                    main.post(new Runnable() {\n                        @Override public void run() { renderSimilar(items); }\n                    });\n                } catch (Exception ignored) {}\n            }\n        });\n    }'''

new_similar_load = '''    private void loadSimilarMovies(final String category) {\n        if (TextUtils.isEmpty(category) || host.length() == 0) return;\n        if (similarStrip != null) showSimilarPlaceholders();\n        final String activeVodId = vodId;\n        final long activeAdded = currentAdded;\n        io.execute(new Runnable() {\n            @Override public void run() {\n                try {\n                    JSONArray arr = new JSONArray(httpGet(apiUrl("get_vod_streams", "&category_id=" + enc(category))));\n                    final ArrayList<SimilarMovie> items = new ArrayList<SimilarMovie>();\n                    int anchor = -1;\n                    for (int i = 0; i < arr.length(); i++) {\n                        JSONObject o = arr.optJSONObject(i);\n                        if (o == null) continue;\n                        String id = o.optString("stream_id", "");\n                        if (id.length() == 0) continue;\n                        if (id.equals(activeVodId)) {\n                            anchor = i;\n                            continue;\n                        }\n                        items.add(new SimilarMovie(\n                                id,\n                                o.optString("name", "Film"),\n                                o.optString("stream_icon", ""),\n                                firstNonEmpty(o.optString("container_extension", ""), "mp4"),\n                                o.optLong("added", 0L),\n                                i));\n                    }\n                    final int anchorIndex = anchor;\n                    Collections.sort(items, new Comparator<SimilarMovie>() {\n                        @Override public int compare(SimilarMovie a, SimilarMovie b) {\n                            if (activeAdded > 0L && a.added > 0L && b.added > 0L) {\n                                long da = Math.abs(a.added - activeAdded);\n                                long db = Math.abs(b.added - activeAdded);\n                                if (da < db) return -1;\n                                if (da > db) return 1;\n                            }\n                            if (anchorIndex >= 0) {\n                                int da = Math.abs(a.sourceIndex - anchorIndex);\n                                int db = Math.abs(b.sourceIndex - anchorIndex);\n                                if (da < db) return -1;\n                                if (da > db) return 1;\n                            }\n                            int ha = (a.id + "|" + activeVodId).hashCode() & 0x7fffffff;\n                            int hb = (b.id + "|" + activeVodId).hashCode() & 0x7fffffff;\n                            if (ha < hb) return -1;\n                            if (ha > hb) return 1;\n                            return a.name.compareToIgnoreCase(b.name);\n                        }\n                    });\n                    main.post(new Runnable() {\n                        @Override public void run() {\n                            if (activeVodId.equals(vodId)) renderSimilar(items);\n                        }\n                    });\n                } catch (Exception ignored) {}\n            }\n        });\n    }'''
rep(old_similar_load, new_similar_load, 'similar refresh logic')

