actor_helpers = '''\n    private ArrayList<ActorEntry> extractActors(JSONObject root, JSONObject info, String fallbackCast) {\n        ArrayList<ActorEntry> out = new ArrayList<ActorEntry>();\n        appendActorValue(out, info == null ? null : info.opt("actors"));\n        appendActorValue(out, root == null ? null : root.opt("actors"));\n        appendActorValue(out, info == null ? null : info.opt("cast"));\n        appendActorValue(out, root == null ? null : root.opt("cast"));\n        if (info != null) {\n            JSONObject credits = info.optJSONObject("credits");\n            if (credits != null) appendActorValue(out, credits.opt("cast"));\n        }\n        if (out.isEmpty()) {\n            ArrayList<String> names = parseCast(fallbackCast);\n            for (String name : names) addActorUnique(out, new ActorEntry(name, ""));\n        }\n        return out;\n    }\n\n    private void appendActorValue(ArrayList<ActorEntry> out, Object value) {\n        if (value == null || value == JSONObject.NULL) return;\n        try {\n            if (value instanceof JSONArray) {\n                JSONArray arr = (JSONArray) value;\n                for (int i = 0; i < arr.length(); i++) {\n                    Object item = arr.opt(i);\n                    if (item instanceof JSONObject) addActorObject(out, (JSONObject) item);\n                    else if (item != null) addActorUnique(out, new ActorEntry(String.valueOf(item).trim(), ""));\n                }\n                return;\n            }\n            if (value instanceof JSONObject) {\n                JSONObject o = (JSONObject) value;\n                Object nested = o.opt("cast");\n                if (nested != null && nested != JSONObject.NULL) appendActorValue(out, nested);\n                else addActorObject(out, o);\n                return;\n            }\n            String raw = String.valueOf(value).trim();\n            if (raw.startsWith("[")) {\n                appendActorValue(out, new JSONArray(raw));\n                return;\n            }\n            if (raw.startsWith("{")) {\n                appendActorValue(out, new JSONObject(raw));\n                return;\n            }\n            ArrayList<String> names = parseCast(raw);\n            for (String name : names) addActorUnique(out, new ActorEntry(name, ""));\n        } catch (Exception ignored) {}\n    }\n\n    private void addActorObject(ArrayList<ActorEntry> out, JSONObject o) {\n        String name = firstNonEmpty(\n                o.optString("name", ""),\n                o.optString("actor_name", ""),\n                o.optString("actor", ""),\n                o.optString("original_name", ""));\n        String image = firstNonEmpty(\n                o.optString("image", ""),\n                o.optString("profile", ""),\n                o.optString("profile_url", ""),\n                o.optString("photo", ""),\n                o.optString("thumb", ""),\n                o.optString("avatar", ""),\n                o.optString("picture", ""));\n        String profilePath = o.optString("profile_path", "");\n        if (TextUtils.isEmpty(image) && !TextUtils.isEmpty(profilePath)) {\n            image = profilePath.startsWith("/")\n                    ? "https://image.tmdb.org/t/p/w342" + profilePath\n                    : profilePath;\n        }\n        if (!TextUtils.isEmpty(name)) addActorUnique(out, new ActorEntry(name, image));\n    }\n\n    private void addActorUnique(ArrayList<ActorEntry> out, ActorEntry actor) {\n        if (actor == null || TextUtils.isEmpty(actor.name)) return;\n        for (ActorEntry existing : out) {\n            if (existing.name.equalsIgnoreCase(actor.name)) return;\n        }\n        out.add(actor);\n    }\n\n    private void loadActorImageFallback(final String actorName, final ImageView target) {\n        if (TextUtils.isEmpty(actorName) || target == null) return;\n        final String marker = "actor:" + actorName;\n        target.setTag(marker);\n        io.execute(new Runnable() {\n            @Override public void run() {\n                try {\n                    String endpoint = "https://en.wikipedia.org/w/api.php?action=query&generator=search"\n                            + "&gsrsearch=" + enc(actorName + " actor")\n                            + "&gsrnamespace=0&gsrlimit=1&prop=pageimages&piprop=thumbnail"\n                            + "&pithumbsize=320&format=json&formatversion=2";\n                    JSONObject response = new JSONObject(httpGet(endpoint));\n                    JSONObject query = response.optJSONObject("query");\n                    JSONArray pages = query == null ? null : query.optJSONArray("pages");\n                    JSONObject page = pages == null || pages.length() == 0 ? null : pages.optJSONObject(0);\n                    JSONObject thumb = page == null ? null : page.optJSONObject("thumbnail");\n                    String source = thumb == null ? "" : thumb.optString("source", "");\n                    if (TextUtils.isEmpty(source)) return;\n                    final Bitmap bitmap = downloadBitmap(source);\n                    if (bitmap == null) return;\n                    main.post(new Runnable() {\n                        @Override public void run() {\n                            Object tag = target.getTag();\n                            if (marker.equals(tag)) target.setImageBitmap(bitmap);\n                        }\n                    });\n                } catch (Exception ignored) {}\n            }\n        });\n    }\n\n    private long parseLongSafe(String raw) {\n        if (TextUtils.isEmpty(raw)) return 0L;\n        try { return Long.parseLong(raw.trim()); }\n        catch (Exception ignored) { return 0L; }\n    }\n'''

