new_similar_class = '''    private static final class ActorEntry {\n        final String name;\n        final String image;\n        ActorEntry(String name, String image) {\n            this.name = name == null ? "" : name;\n            this.image = image == null ? "" : image;\n        }\n    }\n\n    private static final class SimilarMovie {\n        final String id;\n        final String name;\n        final String icon;\n        final String ext;\n        final long added;\n        final int sourceIndex;\n        SimilarMovie(String id, String name, String icon, String ext, long added, int sourceIndex) {\n            this.id = id;\n            this.name = name;\n            this.icon = icon;\n            this.ext = ext;\n            this.added = added;\n            this.sourceIndex = sourceIndex;\n        }\n    }'''
